#Requires -Version 7.6
param([switch]$Emit,[switch]$Write)
$residentEmit=$Emit;$residentWrite=$Write
. "$PSScriptRoot/verify_operation_budget.ps1"
$Emit=$residentEmit;$Write=$residentWrite
$script:ResidentLedger='docs/evidence/hexagon-resident-host-24000-ledger.json'
function Get-ResidentScenario([string]$Name,[long]$Operations,[long]$Original,[long]$Weights,[long]$Activation,[long]$Results,[long]$MaximumOperations) {
    $base=[long]([Math]::Ceiling(([Math]::Ceiling((1024+17408*36)/128)*128+4096+17408*32)/4096)*4096)
    $fits=$Weights -le 67108864;$allocation=if ($fits) {[long]([Math]::Ceiling(($base+$Weights)/4096)*4096)} else {$null}
    return @{placement=$Name;operationsPerToken=$Operations;originalSelectedWeightBytes=$Original;minimumPackedResidentArenaBytes=$Weights;fitsMaximumResidentArena=$fits;minimumOriginalPlusResidentWeightBytes=$Original+$Weights;minimumWeightsFitServiceAllowance=($Original+$Weights -le 12348030976);baseNativeAllocationBytes=$base;nativeAllocationWithMinimumArenaBytes=$allocation;kernelLogicalPayloadPerTokenBytes=$Weights+$Activation+$Results;kernelWeightPayloadPerTokenBytes=$Weights;activationPayloadPerTokenBytes=$Activation;returnedPlanePayloadPerTokenBytes=$Results;baselineDescriptorCoveredExtentPerTokenBytes=$Operations*$base;residentDescriptorCoveredExtentPerTokenBytes=$(if ($null -ne $allocation) {$Operations*$allocation} else {$null});repeatedProjectionCases=@(foreach ($tokens in @(1,8,128)) {@{tokens=$tokens;operations=$Operations*$tokens;fitsTerminalOperationCap=($Operations*$tokens -le $MaximumOperations);streamingCpuPackedWeightBytes=$Weights*$tokens;residentCpuPackedWeightBytesLowerBound=$Weights;avoidedRepeatedCpuPackingBytesUpperBound=$Weights*($tokens-1);kernelLogicalPayloadBytes=($Weights+$Activation+$Results)*$tokens}})}
}
function Get-ResidentTraffic {
    $streaming=Get-OperationTraffic;$budget=Get-OperationBudget
    Assert-Hexagon (Test-HexagonEqual (Read-HexagonJson (Join-Path $script:HexagonRoot $script:BudgetLedger)) $budget) 'current terminal operation budget changed'
    Assert-Hexagon (Test-HexagonEqual (Read-HexagonJson (Join-Path $script:HexagonRoot $script:TrafficLedger)) $streaming) 'streaming source identities or logical payloads changed'
    $first=$streaming.projectionFamilies[0];Assert-Hexagon ($first.tensor -ceq 'blk.*.ffn_up.weight') 'first-projection family changed'
    $fields=@('operations','originalWeightBytes','hmxRepackedWeightBytes','hmxActivationBytes','hmxReturnedPlaneBytes')
    foreach ($field in $fields) {Assert-Hexagon ($first[$field] % 64 -eq 0) 'first-projection family no longer divides into 64 layers'}
    $sources=@('tools/hexagon/verify_resident_traffic.ps1','tools/hexagon/verify_operation_traffic.ps1',$script:OperationLedger,$script:TrafficLedger,$script:BudgetLedger)
    $one=@{};$all=@{};for ($i=0;$i -lt $fields.Count;$i++) {$key=@('Operations','Original','Weights','Activation','Results')[$i];$one[$key]=$first[$fields[$i]]/64;$all[$key]=$streaming.totals[$fields[$i]]}
    return @{schemaVersion=1;kind='static-original-pq2-resident-host-payload-bounds';sourceIdentityEncoding='UTF8-with-LF-newlines';sources=@($sources | ForEach-Object {@{path=$_;sha256=(Get-HexagonHash (Read-HexagonSource $_))}});assumptions=@{maximumWeightRowsPerOperation=17408;terminalOperationCap=$budget.terminalMaximumOperations;maximumResidentArenaBytes=67108864;residentRangeAlignmentBytes=128;allocationAlignmentBytes=4096;swiftServiceAllowanceBytes=12348030976;fullAllocationQueueBufferFlags='0x90';residentArena='immutable packed weights in mapped host RAM; not DSP VTCM';allSelectedWeightsRetainedForEveryRepeatedToken=$true;cacheEviction=$false};scenarios=@((Get-ResidentScenario -Name 'blk.0.ffn_up.weight' @one -MaximumOperations $budget.terminalMaximumOperations),(Get-ResidentScenario -Name 'all-eligible-original-PQ2-plus-logits-idealized' @all -MaximumOperations $budget.terminalMaximumOperations));limitations=@('Conditional byte arithmetic, not runtime admission, actual cache occupancy, measured bandwidth or inference speedup.','The first scenario assumes its complete weight payload is resident and reused; metadata, scales, temporary packing, allocator, CPU graph and DSP resources are additional.','The all-eligible scenario exceeds the 64MiB arena. One evaluation fits the 24000-operation cap; a full prompt and output reserve still need complete-request admission.','Resident mapped host weights remove repeated CPU packing/copy only when hits occur; they do not reduce the signed kernel''s declared weight or returned-plane payloads.','The full expanded allocation remains covered by each queue descriptor with unchanged 0x90 flags; actual cache maintenance may grow and is unmeasured.','Descriptor-covered extent is not bytes transferred, cache-line work, DRAM traffic or simultaneous memory occupancy.','No DSP weight residency, fused kernel, multitoken HMX prefill, persistent service, PTQ1 qualification or production backend is established.','Repeated-token cases are arithmetic examples within operation bounds only, without a duration, numerical, model-state, resource or device acceptance claim.');newOwnerDeviceExecutionMilliseconds=0;deviceOpened=$false;modelLoaded=$false;profileEligible=$false;measuredInferenceSpeedup=$null}
}
if ($MyInvocation.InvocationName -ne '.') {
    Assert-Hexagon (-not ($Emit -and $Write)) 'emit and write are mutually exclusive';$expected=Get-ResidentTraffic
    if ($Write) {Write-HexagonJson (Join-Path $script:HexagonRoot $script:ResidentLedger) $expected} elseif ($Emit) {$expected | ConvertTo-Json -Depth 64} else {Assert-Hexagon (Test-HexagonEqual (Read-HexagonJson (Join-Path $script:HexagonRoot $script:ResidentLedger)) $expected) 'retained resident-host bounds differ from source-derived arithmetic';Write-Output 'Resident-host payload bounds verified; no device, model or speed measurement.'}
}
